import bpy,hashlib,json,struct
from pathlib import Path
from mathutils import Vector
from bpy_extras.object_utils import world_to_camera_view
root=Path('/Users/ffq/Documents/aicoding项目/gis校园地图/model')
bpy.ops.wm.open_mainfile(filepath=str(root/'study/campus.blend'))
s=bpy.context.scene
def meshhash(o):
 h=hashlib.sha256()
 for row in o.matrix_world:h.update(struct.pack('<4f',*row))
 for v in o.data.vertices:h.update(struct.pack('<3f',*v.co))
 for p in o.data.polygons:h.update(struct.pack('<'+'I'*len(p.vertices),*p.vertices))
 return h.hexdigest()
groups={key:s.objects[key+' Central detailed architecture'] for key in ['B06','B07','B08']}
children={key:list(group.children) for key,group in groups.items()}
assert all(g.type=='EMPTY' for g in groups.values())
allnames={o.name:o for group in children.values() for o in group}
with bpy.data.libraries.load(str(root/'central-campus/central-campus.blend'),link=False) as (src,dst):
 names=[n for n in src.objects if n in allnames];dst.objects=list(names)
for ob in dst.objects:s.collection.objects.link(ob)
bpy.context.view_layer.update()
retained={k:[] for k in groups}
for name,source in zip(names,dst.objects):
 target=allnames[name]
 assert meshhash(source)==meshhash(target),name
 retained[target.parent.name[:3]].append({'name':name,'geometry_world_transform_sha256':meshhash(target)})
required={'B06':['B06 roof slab','B06 west lower wing','B06 east lower wing','B06 rear fan canopy'], 'B07':['B07 west courtyard wings','B07 north wing'], 'B08':['B08 north academic bar','B08 lakeside courtyard wings']}
for key,items in required.items():
 assert set(items)<=set(r['name'] for r in retained[key]),key
prefixes={'B06':['B06 continuous ceramic band','B06 recessed window module','B06 satellite entrance canopy'], 'B07':['B07 south photo gable face','B07 north photo gable face','B07 sloped PV module','B07 courtyard grouped window glass','B07 north grouped window glass'], 'B08':['B08 bar grouped classroom window glass','B08 lakeside grouped classroom window glass','B08 observed rooftop grille housing','B08 bar raised roof seam','B08 lakeside raised roof seam']}
result={}
for key,obs in children.items():
 counts={p:sum(o.name.startswith(p) for o in obs) for p in prefixes[key]}
 assert all(counts.values()),counts
 proj=[world_to_camera_view(s,s.camera,o.matrix_world@Vector(c)) for o in obs for c in o.bound_box]
 frame={a:f(getattr(v,b) for v in proj) for a,f,b in [('xmin',min,'x'),('xmax',max,'x'),('ymin',min,'y'),('ymax',max,'y')]}
 assert all(0<v.x<1 and 0<v.y<1 for v in proj),(key,frame)
 for o in obs:
  assert o.type=='MESH' and len(o.data.vertices)>0,o.name
  if any(q in o.name for q in ['mullion','transom','pilaster','full-height pier','grille housing']):assert min(o.dimensions)>1e-5,o.name
 result[key]={'components':len(obs),'retained_source_components':retained[key],'retained_count':len(retained[key]),'feature_counts':counts,'main_camera_bounds':frame}
assert result['B06']['feature_counts']['B06 continuous ceramic band']==8
assert result['B07']['feature_counts']['B07 south photo gable face']==2
assert result['B07']['feature_counts']['B07 north photo gable face']==2
assert result['B08']['feature_counts']['B08 observed rooftop grille housing']==2
h=hashlib.sha256()
for o in sorted(children['B06'],key=lambda x:x.name):
 h.update(o.name.encode())
 for row in o.matrix_world:h.update(struct.pack('<4f',*row))
 for v in o.data.vertices:h.update(struct.pack('<3f',*v.co))
 for p in o.data.polygons:h.update(struct.pack('<'+'I'*len(p.vertices),*p.vertices))
assert h.hexdigest()=='988d25455ac4e4a8a14c7ae37639219685a1670260fa503bc62b7d0957966817'
result['b06_geometry_unchanged_from_previous_study']=h.hexdigest()
result['render']=[s.render.resolution_x,s.render.resolution_y];result['renderer']=s.render.engine;result['samples']=s.cycles.samples
result['source_positioned_canopies']=sum(o.name.startswith('Observed canopy ') for o in s.objects)
result['packed_source_images']=[i.name for i in bpy.data.images if i.packed_file]
result['surveyed']=False
Path('/tmp/taihu-study/verification.json').write_text(json.dumps(result,ensure_ascii=False,indent=2))
print('VERIFIED', {k:{a:b for a,b in v.items() if a!='retained_source_components'} if isinstance(v,dict) else v for k,v in result.items()})

