cache={}
def norm(v):
 if isinstance(v,(str,bool,int,float)):return v
 try:return list(v)
 except:return str(v)
def graph(nt):
 if not nt:return None
 nodes=[]
 for n in nt.nodes:
  values={i.name:norm(i.default_value) for i in n.inputs if hasattr(i,'default_value')}
  attrs={a:norm(getattr(n,a)) for a in ['operation','blend_type','interpolation','extension','noise_dimensions','vector_type','convert_from','convert_to'] if hasattr(n,a)}
  if hasattr(n,'color_ramp'):attrs['ramp']=[(e.position,list(e.color)) for e in n.color_ramp.elements]
  if getattr(n,'image',None):attrs['image']=str(Path(n.image.filepath).name)
  if getattr(n,'object',None):attrs['object']=n.object.name
  nodes.append((n.name,n.bl_idname,values,attrs))
 return {'nodes':nodes,'links':[(l.from_node.name,l.from_socket.name,l.to_node.name,l.to_socket.name) for l in nt.links]}
def dh(data):
 k=data.as_pointer()
 if k in cache:return cache[k]
 h=hashlib.sha256()
 if isinstance(data,bpy.types.Mesh):
  for v in data.vertices:h.update(struct.pack('<3f',*v.co))
  for p in data.polygons:h.update(struct.pack('<'+'I'*len(p.vertices),*p.vertices));h.update(struct.pack('<I?',p.material_index,p.use_smooth))
 elif isinstance(data,bpy.types.Curve):
  h.update(str((data.bevel_depth,data.bevel_resolution)).encode())
  for sp in data.splines:
   for p in sp.points:h.update(struct.pack('<4f',*p.co))
 elif isinstance(data,bpy.types.Light):h.update(str((data.type,data.energy,list(data.color),getattr(data,'angle',None))).encode())
 elif isinstance(data,bpy.types.Camera):h.update(str((data.type,data.ortho_scale,data.lens,data.clip_start,data.clip_end)).encode())
 cache[k]=h.hexdigest();return cache[k]
records={}
for ob in s.objects:
 mats=[graph(m.node_tree) if m else None for m in getattr(ob.data,'materials',[])]
 rec=[ob.type,[list(row) for row in ob.matrix_world],dh(ob.data) if ob.data else None,mats,ob.hide_render,[(m.type,getattr(m,'width',None),getattr(m,'segments',None)) for m in ob.modifiers]]
 records[ob.name]=hashlib.sha256(json.dumps(rec,sort_keys=True).encode()).hexdigest()
result={'objects':records,'world':graph(s.world.node_tree),'render':[s.render.engine,s.cycles.samples,s.render.resolution_x,s.render.resolution_y,s.view_settings.view_transform,s.view_settings.look,s.view_settings.exposure,s.camera.name]}
p=Path('/tmp/taihu-study/visual-baseline.json')
if '--baseline' in sys.argv:p.write_text(json.dumps(result));print('BASELINE',len(records))
else:
 old=json.loads(p.read_text());delta=[n for n in set(records)|set(old['objects']) if records.get(n)!=old['objects'].get(n)];print('VISUAL OBJECT DIFFERENCES',delta[:30],len(delta));assert not delta;assert json.dumps(old['world'],sort_keys=True)==json.dumps(result['world'],sort_keys=True);assert old['render']==result['render'];Path('/tmp/taihu-study/visual-preservation.json').write_text(json.dumps({'visible_object_count':len(records),'scene_render_fingerprint_sha256':hashlib.sha256(json.dumps(result,sort_keys=True).encode()).hexdigest(),'scene_visual_state_preserved':True}));print('VISUAL STATE PRESERVED')
